<?php
namespace App\Http\Requests\Business;
use Illuminate\Foundation\Http\FormRequest;
class BusinessRequest extends FormRequest { public function authorize(): bool { return (bool)($this->user()?->hasRole('business_owner')||$this->user()?->hasRole('admin')); } public function rules(): array { return ['name'=>['required','string','max:120'],'category'=>['nullable','string','max:120'],'services'=>['nullable','array','max:30'],'services.*'=>['string','max:120'],'description'=>['nullable','string','max:5000'],'phone'=>['nullable','string','max:30'],'email'=>['nullable','email','max:255'],'address'=>['nullable','string','max:1000'],'city'=>['nullable','string','max:120'],'neighborhood'=>['nullable','string','max:120'],'latitude'=>['nullable','numeric','between:-90,90'],'longitude'=>['nullable','numeric','between:-180,180'],'social_links'=>['nullable','array'],'social_links.*'=>['nullable','url','max:500']]; } protected function prepareForValidation(): void { foreach(['name','category','description','phone','email','address','city','neighborhood'] as $field) if(is_string($this->input($field))) $this->merge([$field=>trim($this->input($field))]); } }
